import React, { useState } from 'react';
import { AudioDescSettingsProps } from '../types/player';

const AudioDescSettingsModal: React.FC<AudioDescSettingsProps> = ({
  open,
  onClose,
  voices,
  selectedVoice,
  setSelectedVoice,
  pitch,
  setPitch,
  autoStop,
  setAutoStop,
  autoStart,
  setAutoStart,
  mode,
  setMode,
  hasAudioTrack,
  hasSignTrack,
  ttsAvailable,
  ttsError
}) => {
  const [testText, setTestText] = useState('Audiodeskription Test');
  
  const handleTest = () => {
    if (!ttsAvailable) return;
    const utter = new window.SpeechSynthesisUtterance(testText);
    utter.voice = voices.find(v => v.voiceURI === selectedVoice) || null;
    utter.pitch = pitch;
    window.speechSynthesis.speak(utter);
  };

  if (!open) return null;

  return (
    <div 
      role="dialog" 
      aria-modal="true" 
      style={{ 
        position: 'fixed', 
        top: 0, 
        left: 0, 
        width: '100vw', 
        height: '100vh', 
        background: 'rgba(0,0,0,0.3)', 
        zIndex: 1000, 
        display: 'flex', 
        alignItems: 'center', 
        justifyContent: 'center' 
      }}
    >
      <div style={{ 
        background: '#fff', 
        borderRadius: 8, 
        padding: 24, 
        minWidth: 320, 
        maxWidth: 400 
      }}>
        <h2 id="ad-modal-title" style={{ marginTop: 0 }}>
          Audiodeskription Einstellungen
        </h2>
        
        <label>Modus:</label>
        <select 
          value={mode} 
          onChange={e => setMode(e.target.value)} 
          style={{ width: '100%', marginBottom: 12 }}
        >
          <option value="tts">Transkript vorlesen</option>
          <option value="audio" disabled={!hasAudioTrack}>
            Zur Audiospur wechseln {hasAudioTrack ? '' : '(nicht verfügbar)'}
          </option>
          <option value="sign" disabled={!hasSignTrack}>
            Gebärdensprache-Overlay {hasSignTrack ? '' : '(nicht verfügbar)'}
          </option>
        </select>

        {mode === 'tts' && (
          <>
            <label htmlFor="ad-voice">Stimme:</label>
            <select 
              id="ad-voice" 
              value={selectedVoice} 
              onChange={e => setSelectedVoice(e.target.value)} 
              style={{ width: '100%', marginBottom: 12 }}
            >
              {voices.map(v => (
                <option key={v.voiceURI} value={v.voiceURI}>
                  {v.name} ({v.lang})
                </option>
              ))}
            </select>

            <label htmlFor="ad-pitch">Pitch: {pitch.toFixed(2)}</label>
            <input 
              id="ad-pitch" 
              type="range" 
              min={0.5} 
              max={2} 
              step={0.01} 
              value={pitch} 
              onChange={e => setPitch(Number(e.target.value))} 
              style={{ width: '100%' }} 
            />

            <div style={{ margin: '12px 0' }}>
              <label>
                <input 
                  type="checkbox" 
                  checked={autoStop} 
                  onChange={e => setAutoStop(e.target.checked)} 
                /> 
                Video automatisch stoppen
              </label>
              <br />
              <label>
                <input 
                  type="checkbox" 
                  checked={autoStart} 
                  onChange={e => setAutoStart(e.target.checked)} 
                /> 
                Video nach Vorlesen automatisch starten
              </label>
            </div>

            <label htmlFor="ad-test">Testtext:</label>
            <input 
              id="ad-test" 
              type="text" 
              value={testText} 
              onChange={e => setTestText(e.target.value)} 
              style={{ width: '100%' }} 
            />
            <button 
              style={{ margin: '8px 0' }} 
              onClick={handleTest} 
              disabled={!ttsAvailable}
            >
              Stimme testen
            </button>
            {!ttsAvailable && (
              <div style={{ color: 'red', marginTop: 8 }}>
                {ttsError || 'Text-to-Speech nicht verfügbar!'}
              </div>
            )}
          </>
        )}

        {mode === 'audio' && (
          <div style={{ margin: '12px 0', color: hasAudioTrack ? '#333' : '#aaa' }}>
            Zur Audiospur wechseln {hasAudioTrack ? '' : '(nicht verfügbar)'}
          </div>
        )}

        {mode === 'sign' && (
          <div style={{ margin: '12px 0', color: hasSignTrack ? '#333' : '#aaa' }}>
            Gebärdensprache-Overlay {hasSignTrack ? '' : '(nicht verfügbar)'}
          </div>
        )}

        <div style={{ display: 'flex', justifyContent: 'flex-end', gap: 8 }}>
          <button onClick={onClose}>Schließen</button>
        </div>
      </div>
    </div>
  );
};

export default AudioDescSettingsModal;